  {
   "@type": "Question",
   "name": "Is it okay if my dog doesn't poop for a day?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "A day can happen, but if it goes longer and your dog strains or seems uncomfortable, talk to your vet."
   }
  },
  {
   "@type": "Question",
   "name": "Should I see a vet if the potty interval suddenly changes?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "If the interval gets much longer or shorter than usual and it lasts a few days, talk to your vet."
   }
  }
